mapper.select:
SELECT DATE(c.commit_time) AS stat_date,
c.user_id AS user_id,
COUNT(*) AS commit_count,
COALESCE(SUM(c.add_lines), 0) AS add_lines,
COALESCE(SUM(c.del_lines), 0) AS del_lines

AND c.commit_time >= #{begin}
AND c.commit_time <= #{end}
AND c.user_id = #{userId}
AND c.project_id = #{projectId}
GROUP BY DATE(c.commit_time), c.user_id
ORDER BY stat_date

SELECT COUNT(*) FROM (
SELECT c.user_id AS user_id

AND c.commit_time >= #{begin}
AND c.commit_time <= #{end}
GROUP BY c.user_id
HAVING COUNT(*) > #{commitCount}
) t
